    sse_encode_String(self.protocol, serializer);
    sse_encode_bool(self.isGroup, serializer);
    sse_encode_opt_box_autoadd_i_32(self.delay, serializer);
    sse_encode_opt_box_autoadd_i_32(self.realDelay, serializer);
