  @protected
  void sse_encode_ui_event(UiEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case UiEvent_Status():
        sse_encode_i_32(0, serializer);
      case UiEvent_Log():
        sse_encode_i_32(1, serializer);
      case UiEvent_Traffic(up: final up, down: final down):
        sse_encode_i_32(2, serializer);
        sse_encode_i_64(up, serializer);
        sse_encode_i_64(down, serializer);
      case UiEvent_Subscriptions():
        sse_encode_i_32(3, serializer);
      case UiEvent_Settings():
        sse_encode_i_32(4, serializer);
      case UiEvent_CoreInfo():
        sse_encode_i_32(5, serializer);
      case UiEvent_Proxies():
        sse_encode_i_32(6, serializer);
      case UiEvent_Delays():
        sse_encode_i_32(7, serializer);
      case UiEvent_RuleProviders():
        sse_encode_i_32(8, serializer);
      case UiEvent_Notice(kind: final kind, key: final key, args: final args):
        sse_encode_i_32(9, serializer);
        sse_encode_notice_level(kind, serializer);
        sse_encode_String(key, serializer);
        sse_encode_list_String(args, serializer);
    }
  }

